{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/nav-actions.json
    The buttons at the end of a top bar: login, the call to action and the theme button (it only reports the press). No wrapper: they sit in the row of the bar.
    Props (p): login, loginHref, cta, ctaHref, actions, tone, themeLabel. *}
{var $v_login = ($p['login'] ?? null)}
{var $v_loginHref = ($p['loginHref'] ?? null)}
{var $v_cta = ($p['cta'] ?? null)}
{var $v_ctaHref = ($p['ctaHref'] ?? null)}
{var $v_actions = ($p['actions'] ?? 'cta')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_themeLabel = ($p['themeLabel'] ?? null)}
{if og_t($v_login)}
  {capture $c_1}
    {=og_text($v_login)}
  {/capture}
  {=og_include('compose/Button.latte', ['variant' => 'ghost', 'size' => 'sm', 'href' => og_url(og_s($v_loginHref)), 'class' => og_s((og_t(og_eq($v_tone, 'inverse')) ? 'text-background hover:bg-background/10' : '')), 'attrs' => og_attrs(['data-testid', 'nav-login']), 'children' => (string) $c_1])|noescape}
{/if}
{if og_t(og_and([og_eq($v_actions, 'cta'), $v_cta]))}
  {capture $c_2}
    {=og_text($v_cta)}
  {/capture}
  {=og_include('compose/Button.latte', ['variant' => og_s((og_t(og_eq($v_tone, 'inverse')) ? 'secondary' : 'default')), 'size' => 'sm', 'href' => og_url(og_s($v_ctaHref)), 'attrs' => og_attrs(['data-testid', 'header-cta']), 'children' => (string) $c_2])|noescape}
{/if}
{if og_t($v_themeLabel)}
  {capture $c_3}
    {=og_text($v_themeLabel)}
  {/capture}
  {=og_include('compose/Button.latte', ['variant' => 'outline', 'size' => 'sm', 'attrs' => og_attrs(['data-testid', 'theme-toggle']), 'children' => (string) $c_3])|noescape}
{/if}
